// src/pages/DashboardProf.jsx
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import './DashboardProf.css';

function DashboardProf() {
  const [user, setUser] = useState({});
  const [stats, setStats] = useState({
    totalCours: 0,
    etudiantsInscrits: 0,
    evaluations: 0,
    moyenneGenerale: 0
  });
  const [recentCours, setRecentCours] = useState([]);
  const [deadlines, setDeadlines] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchData = async () => {
      const token = localStorage.getItem('token');
      if (!token) {
        navigate('/login');
        return;
      }

      try {
        // Récupérer les infos du professeur
        const userRes = await axios.get('http://localhost:5000/api/profs/me', {
          headers: { Authorization: `Bearer ${token}` }
        });
        setUser(userRes.data);

        // Données de démonstration - à remplacer par vos appels API
        setStats({
          totalCours: 12,
          etudiantsInscrits: 145,
          evaluations: 8,
          moyenneGenerale: 15.5
        });

        // Cours de démonstration
        setRecentCours([
          {
            _id: 1,
            titre: "Mathématiques Avancées",
            description: "Cours de mathématiques pour niveau avancé",
            nombreEtudiants: 45,
            dateCreation: new Date()
          },
          {
            _id: 2,
            titre: "Physique Quantique",
            description: "Introduction à la physique quantique",
            nombreEtudiants: 32,
            dateCreation: new Date()
          }
        ]);

      } catch (err) {
        console.error('Erreur détaillée:', err);
        if (err.response?.status === 401) {
          localStorage.removeItem('token');
          navigate('/login');
        } else {
          alert('Erreur lors du chargement des données');
        }
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  const handleCreateCours = () => {
    navigate('/creer-cours');
  };

  if (isLoading) {
    return (
      <div className="dashboard-loading">
        <div className="loading-spinner"></div>
        <p>Chargement de votre espace...</p>
      </div>
    );
  }

  return (
    <div className="dashboard-prof">
      {/* Header */}
      <header className="dashboard-header">
        <div className="header-content">
          <div className="welcome-section">
            <h1>Bonjour, Professeur {user.nom} 👨‍🏫</h1>
            <p>Bienvenue dans votre espace d'enseignement</p>
          </div>
          <div className="header-actions">
            <button className="profile-btn">
              <span className="user-avatar">
                {user.nom?.charAt(0).toUpperCase()}
              </span>
              Mon Profil
            </button>
            <button onClick={handleLogout} className="logout-btn">
              Déconnexion
            </button>
          </div>
        </div>
      </header>

      <div className="dashboard-content">
        {/* Statistiques - TOUT SUR LA MÊME LIGNE */}
        <section className="stats-section">
          <h2 className="section-title">Vue d'ensemble</h2>
          <div className="stats-container">
            <div className="stats-row">
              <div className="stat-item">
                <div className="stat-icon-wrapper">
                  <span className="stat-icon">📚</span>
                </div>
                <div className="stat-text">
                  <h3 className="stat-number">{stats.totalCours}</h3>
                  <p className="stat-label">Cours créés</p>
                </div>
              </div>
              
              <div className="stat-item">
                <div className="stat-icon-wrapper">
                  <span className="stat-icon">👥</span>
                </div>
                <div className="stat-text">
                  <h3 className="stat-number">{stats.etudiantsInscrits}</h3>
                  <p className="stat-label">Étudiants inscrits</p>
                </div>
              </div>
              
              <div className="stat-item">
                <div className="stat-icon-wrapper">
                  <span className="stat-icon">📊</span>
                </div>
                <div className="stat-text">
                  <h3 className="stat-number">{stats.evaluations}</h3>
                  <p className="stat-label">Évaluations</p>
                </div>
              </div>
              
              <div className="stat-item">
                <div className="stat-icon-wrapper">
                  <span className="stat-icon">⭐</span>
                </div>
                <div className="stat-text">
                  <h3 className="stat-number">{stats.moyenneGenerale}/20</h3>
                  <p className="stat-label">Moyenne générale</p>
                </div>
              </div>
            </div>
          </div>
        </section>

        <div className="dashboard-main">
          {/* Cours récents */}
          <section className="recent-cours-section">
            <div className="section-header">
              <h2 className="section-title">Mes Cours</h2>
              <button className="primary-btn" onClick={handleCreateCours}>
                + Nouveau cours
              </button>
            </div>
            
            <div className="cours-container">
              {recentCours.length > 0 ? (
                <div className="cours-grid">
                  {recentCours.map((cours) => (
                    <div key={cours._id} className="cours-card">
                      <div className="cours-header">
                        <h3 className="cours-title">{cours.titre}</h3>
                        <span className="status-badge active">
                          Actif
                        </span>
                      </div>
                      <p className="cours-description">
                        {cours.description}
                      </p>
                      <div className="cours-footer">
                        <div className="cours-meta">
                          <span className="meta-item">
                            👥 {cours.nombreEtudiants} étudiants
                          </span>
                          <span className="meta-item">
                            📅 Créé le {new Date().toLocaleDateString()}
                          </span>
                        </div>
                        <div className="cours-actions">
                          <button className="btn-secondary">Voir</button>
                          <button className="btn-primary">Modifier</button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="empty-cours-state">
                  <div className="empty-icon">📚</div>
                  <h3>Aucun cours créé</h3>
                  <p>Commencez par créer votre premier cours</p>
                  <button className="primary-btn large" onClick={handleCreateCours}>
                    Créer un cours
                  </button>
                </div>
              )}
            </div>
          </section>

          {/* Sidebar */}
          <aside className="dashboard-sidebar">
            {/* Actions rapides */}
            <div className="sidebar-card">
              <h3 className="sidebar-title">Actions rapides</h3>
              <div className="quick-actions">
                <button className="quick-action-btn" onClick={handleCreateCours}>
                  <span className="action-icon">➕</span>
                  <span className="action-text">Nouveau cours</span>
                </button>
                <button className="quick-action-btn">
                  <span className="action-icon">📝</span>
                  <span className="action-text">Créer évaluation</span>
                </button>
                <button className="quick-action-btn">
                  <span className="action-icon">👥</span>
                  <span className="action-text">Gérer étudiants</span>
                </button>
                <button className="quick-action-btn">
                  <span className="action-icon">📊</span>
                  <span className="action-text">Voir statistiques</span>
                </button>
              </div>
            </div>

            {/* Prochaines échéances */}
            <div className="sidebar-card">
              <h3 className="sidebar-title">Prochaines échéances</h3>
              <div className="deadlines-list">
                <div className="empty-deadlines">
                  <p className="no-deadlines-text">Aucune échéance prochaine</p>
                </div>
              </div>
            </div>
          </aside>
        </div>
      </div>
    </div>
  );
}

export default DashboardProf;
